    console.log(cpToSubtract)

    currencyToUse.cp -= cpToSubtract;

    return currencyToUse
}

async function addUpdateHandlers(html, actor) {
    html.find('[name="lifestyleSelect"]').on("change", () => {
        var lifestyle = html.find('[name="lifestyleSelect"]')[0].value;
        var totalCp = getTotalCP(actor.system.currency);
        var data = lifestyleData[lifestyle];

        var infoText = '';
        if (totalCp < data.cp) {
            infoText = `You do not have enough CP for the ${data.displayName} lifestyle.`
        } else {
            infoText = `${data.displayName} - Rest DC: ${data.dc}, Downtime Days: ${data.downtime}.`
            if (data.dc === 0) {
                infoText = `${data.displayName} - No roll required.`
                if (lifestyle === 'aristocratic') {
                    infoText += ' Long rest also recovers all hit die.'
                }
            }
        }
        var infoLabel = html.find('[id="additionalInfo"]')[0]
        infoLabel.innerHTML = `<p>${infoText}</p>`
    });
}

async function attemptRest(html, actor) {
    var lifestyle = html.find('[name="lifestyleSelect"]')[0].value;
    if (!lifestyle) return;

    var data = lifestyleData[lifestyle];
    var totalCp = getTotalCP(actor.system.currency);
    if (totalCp < data.cp) {
        ChatMessage.create({
            content: `${actor.name} does not have enough CP for the ${data.displayName} lifestyle.`
        });
        return;
    }

    await actor.update({'system.currency': subtractCP(actor.system.currency, data.cp)});
    if (data.dc === 0) {
        ChatMessage.create({
            content: `${actor.name} spent ${data.cp} CP and succeeds at taking a long rest. (${data.displayName} lifestyle).`
        })
    } else {
        var roll = await new Roll('1d20').roll({async: true});
        var restSuccessText = '<error>'
        if (roll.total < data.dc) {
            restSuccessText = 'but failed to take a long rest';
        } else {
            restSuccessText = 'and succeeded at taking a long rest';
        }

        ChatMessage.create({
            type: CONST.CHAT_MESSAGE_TYPES.ROLL,
            rolls: [roll],
            rollMode: game.settings.get("core", "rollMode"),
            user: game.user._id,
            speaker: ChatMessage.getSpeaker({token: actor}),
            flavor: `${actor.name} spent ${data.cp} CP ${restSuccessText}. (${data.displayName} lifestyle).`
        })
    }
}

let lifestyleOptions = Object.entries(lifestyleData).map(([k, data]) => {
    return `<option value=${k}>${data.displayName} (${data.cp} CP)</option>`
}).reduce((r,opt) => r.concat(opt), '<option disabled value selected />')

if (!token) return;

let lifestyleSelector = `
    <div>
    <label>Select lifestyle:</label>
    <select id="lifestyleSelect" name="lifestyleSelect">${lifestyleOptions}</select>
    </div>`

let dialogHtml = `
    <div>${lifestyleSelector}</div>
    <div><label id="additionalInfo"><p/></label></div>
`

let d = new Dialog({
    title: "Lifestyle Rest",
    content: dialogHtml,
    buttons: {
        reload: {
            label: "Attempt to Rest",
            callback: (html) => attemptRest(html, token.actor)
        },
        cancel: {
            label: "Cancel",
            callback: () => {}
        }
    },
    render: (html) => {
        addUpdateHandlers(html, token.actor)
    }
}).render(true)
